	/** 
	 * updating a SoftwareLoad.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a SoftwareLoad." );

		StringBuilder msg = new StringBuilder( "Failed to update a SoftwareLoad : " );        
		SoftwareLoad entity = read();
		UpdateSoftwareLoadCommand command = generateUpdateCommand();
		command.setSoftwareLoadId(entity.getSoftwareLoadId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created SoftwareLoad." );

			// for use later on...
			softwareLoadId = entity.getSoftwareLoadId();

			SoftwareLoadService proxy = SoftwareLoadService.getSoftwareLoadInstance();  

			proxy.updateSoftwareLoad( command ).get();

			LOGGER.info( "-- Successfully saved SoftwareLoad - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + softwareLoadId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a SoftwareLoad.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created SoftwareLoad." );

		SoftwareLoad entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read SoftwareLoad with id " + softwareLoadId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read SoftwareLoad with id " + softwareLoadId );

			throw e;
		}

		try{
			SoftwareLoadService.getSoftwareLoadInstance().delete( new DeleteSoftwareLoadCommand( entity.getSoftwareLoadId() ) ).get();
			LOGGER.info( "-- Successfully deleted SoftwareLoad with id " + softwareLoadId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete SoftwareLoad with id " + softwareLoadId );

			throw e;
		}
	}

